#!/usr/bin/env python3
"""Hourly station product: python3 hourly.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime, timezone
from fractions import Fraction

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")

CONV = {
    ("temp", "degC"): lambda v: v,
    ("temp", "degF"): lambda v: (v - 32) * 5 / 9,
    ("temp", "K"): lambda v: v - Fraction("273.15"),
    ("rh", "pct"): lambda v: v,
    ("rh", "frac"): lambda v: v * 100,
    ("pres", "hPa"): lambda v: v,
    ("pres", "kPa"): lambda v: v * 10,
    ("pres", "inHg"): lambda v: v * Fraction("33.8638866667"),
    ("pres", "mmHg"): lambda v: v * Fraction("1.33322387415"),
    ("wspd", "ms"): lambda v: v,
    ("wspd", "kmh"): lambda v: v / Fraction("3.6"),
    ("wspd", "kn"): lambda v: v * 1852 / 3600,
    ("wspd", "mph"): lambda v: v * Fraction("0.44704"),
    ("wdir", "deg"): lambda v: v,
    ("rain", "mm"): lambda v: v,
}
CANON = {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms", "wdir": "deg", "rain": "mm"}
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}

DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING = re.compile(r"^-9999(\.0*)?$")
TIME_RE = re.compile(r"(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d):(\d\d)")
EPOCH = datetime(1970, 1, 1)


def parse_time(s):
    """Logger time text -> seconds since epoch (as if UTC)."""
    m = TIME_RE.fullmatch(s.strip())
    y, mo, d, h, mi, se = (int(x) for x in m.groups())
    return int((datetime(y, mo, d, h, mi, se) - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s in ("Z", "z"):
        return 0
    sign = -1 if s[0] == "-" else 1
    body = s[1:]
    hh, mm = body.split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def converter(q, unit):
    if unit == CANON[q]:
        return None
    if q == "rain" and unit.startswith("tips:"):
        try:
            s = Fraction(unit[5:])
        except (ValueError, ZeroDivisionError):
            return None
        return lambda v: v * s
    return CONV.get((q, unit))


def read_value(text, q, conv):
    t = text.strip()
    if t == "" or t == "---" or t.lower() == "nan" or MISSING.match(t):
        return None
    try:
        v = Fraction(t)
    except (ValueError, ZeroDivisionError):
        return None
    if conv is not None:
        v = conv(v)
    lo, hi = RANGES[q]
    if v < lo or v > hi:
        return None
    return v


def parse_file(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw.startswith(b"\xef\xbb\xbf"):
        raw = raw[3:]
    text = raw.decode("utf-8", errors="replace")
    info = {"station": None, "upload": 0, "interval": None, "tz": 0}
    columns = None
    units = {}
    convs = {}
    rows = []   # (logger_utc, {q: Fraction})
    syncs = []  # (logger_utc, ref_utc)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key == "station":
                info["station"] = val
            elif key == "upload":
                info["upload"] = int(val)
            elif key == "interval":
                info["interval"] = int(float(val))
            elif key == "tz":
                info["tz"] = parse_tz(val)
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
            elif key == "units":
                for part in val.split():
                    if "=" in part:
                        q, u = part.split("=", 1)
                        if q in CANON:
                            units[q] = u
                            convs[q] = converter(q, u)
            elif key == "sync":
                lm = re.search(r"logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)", val)
                rm = re.search(r"ref=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)Z?", val)
                if lm and rm:
                    syncs.append((parse_time(lm.group(1)) - info["tz"], parse_time(rm.group(1))))
            continue
        if columns is None:
            continue
        fields = line.split(",")
        vals = {}
        t = None
        for name, field in zip(columns, fields):
            if name == "time":
                t = parse_time(field)
            elif name in CANON:
                vals[name] = read_value(field, name, convs.get(name))
        if t is None:
            continue
        rows.append((t - info["tz"], vals))
    return info, rows, syncs


def floor_div(a, b):
    return a // b


def offset_at(t, pts):
    """pts: sorted list of (t, offset)."""
    if not pts:
        return 0
    if t <= pts[0][0]:
        return pts[0][1]
    if t >= pts[-1][0]:
        return pts[-1][1]
    lo, hi = 0, len(pts) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if pts[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    t1, o1 = pts[lo]
    t2, o2 = pts[hi]
    if t == t1:
        return o1
    return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)


def hour_end(c):
    return -((-c) // 3600) * 3600


def fmt_hour(h):
    return datetime.fromtimestamp(h, tz=timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")


def rnd(x):
    return round(float(x), 2)


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        info, rows, syncs = parse_file(p)
        sid = info["station"]
        if sid is None:
            continue
        st = stations.setdefault(sid, {"interval": info["interval"], "rows": {}, "syncs": {}})
        if st["interval"] is None:
            st["interval"] = info["interval"]
        up = info["upload"]
        for t, vals in rows:
            cur = st["rows"].get(t)
            if cur is None or up >= cur[0]:
                st["rows"][t] = (up, vals)
        for t, ref in syncs:
            cur = st["syncs"].get(t)
            if cur is None or up >= cur[0]:
                st["syncs"][t] = (up, ref)

    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"] or 60
        pts = sorted((t, ref - t) for t, (up, ref) in st["syncs"].items())
        recs = []
        for t, (up, vals) in st["rows"].items():
            c = t + offset_at(t, pts)
            recs.append((c, t, vals))
        recs.sort(key=lambda r: (r[0], r[1]))
        first = hour_end(recs[0][0])
        last = hour_end(max(r[0] for r in recs))
        expected = 3600 / interval
        buckets = {}
        for c, t, vals in recs:
            buckets.setdefault(hour_end(c), []).append((c, vals))

        # rain increments
        incr = {}  # id(row vals) -> increment
        prev = None
        for c, t, vals in recs:
            r = vals.get("rain")
            if r is None:
                continue
            if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                p = prev[1]
                incr[id(vals)] = r - p if r >= p else r
            prev = (c, r)

        hours = []
        h = first
        while h <= last:
            entry = {"hour": fmt_hour(h)}
            rows_h = buckets.get(h, [])
            for q in QUANTITIES:
                reads = [(vals[q], vals) for c, vals in rows_h if vals.get(q) is not None]
                n = len(reads)
                value = None
                if n > 0 and n * 4 >= expected * 3:
                    if q == "rain":
                        value = rnd(sum((incr.get(id(v), 0) for _, v in reads), Fraction(0)))
                    elif q == "wdir":
                        sx = sy = 0.0
                        k = 0
                        for d, v in reads:
                            w = v.get("wspd")
                            if w is not None and w > 0:
                                a = math.radians(float(d))
                                sx += math.sin(a)
                                sy += math.cos(a)
                                k += 1
                        if k and math.hypot(sx, sy) > 1e-9:
                            deg = math.degrees(math.atan2(sx, sy)) % 360.0
                            value = rnd(deg)
                            if value >= 360.0:
                                value = 0.0
                    else:
                        value = rnd(sum((x for x, _ in reads), Fraction(0)) / n)
                entry[q] = {"value": value, "n": n}
            hours.append(entry)
            h += 3600
        result.append({"station": sid, "interval_s": interval, "hours": hours})

    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"stations": result}, f)


if __name__ == "__main__":
    main()
